function settingsTab(w){if(w==='security')return `<div class="settings-card"><div class="section-title">Account & Security</div><div class="section-sub">Protect your administrator account and control login security.</div><div class="profile-grid"><div><label class="form-label">Current Password</label><input id="curPass" type="password" class="form-control-custom"></div><div><label class="form-label">New Password</label><input id="newPass" type="password" class="form-control-custom"></div><div><label class="form-label">Two-Factor Authentication</label><select class="form-select-custom"><option>Enabled</option><option>Disabled</option></select></div><div><label class="form-label">Session Timeout</label><select class="form-select-custom"><option>30 minutes</option><option>1 hour</option><option>4 hours</option></select></div></div><div class="text-end mt-3"><button class="dark-btn" onclick="toast('Security settings saved')">Save Security Settings</button></div></div>`;if(w==='notifications')return `<div class="settings-card"><div class="section-title">Notification Preferences</div><div class="section-sub">Choose which admin alerts you want to receive.</div><div class="quick-cards"><div class="quick-card"><b>New Bookings</b><small>Notify me when a new booking is created.</small><label class="form-label mt-3"><input type="checkbox" checked> Email alerts</label></div><div class="quick-card"><b>Payment Alerts</b><small>Notify me about successful and failed payments.</small><label class="form-label mt-3"><input type="checkbox" checked> Email alerts</label></div><div class="quick-card"><b>Feedback Alerts</b><small>Notify me when attendees leave feedback.</small><label class="form-label mt-3"><input type="checkbox"> Email alerts</label></div></div><div class="text-end mt-3"><button class="dark-btn" onclick="toast('Notification preferences saved')">Save Preferences</button></div></div>`;if(w==='website')return `<div class="settings-card"><div class="section-title">Website Configuration</div><div class="section-sub">Control the public Eventify platform settings.</div><div class="profile-grid"><div><label class="form-label">Website Name</label><input class="form-control-custom" value="Eventify"></div><div><label class="form-label">Default Currency</label><select class="form-select-custom"><option>₹ Indian Rupee (INR)</option></select></div><div><label class="form-label">Support Email</label><input class="form-control-custom" value="support@eventify.com"></div><div><label class="form-label">Timezone</label><select class="form-select-custom"><option>Asia/Kolkata (IST)</option></select></div><div class="full"><label class="form-label">Homepage Announcement</label><textarea class="form-control-custom textarea-custom"></textarea></div></div><div class="text-end mt-3"><button class="dark-btn" onclick="toast('Website settings saved')">Save Website Settings</button></div></div>`;return `<div class="settings-card"><div class="section-title">Public Profile</div><div class="section-sub">This information will be displayed as the administrator identity across the platform.</div><div class="profile-head"><div class="profile-photo"></div><div><b>Profile Picture</b><small class="d-block text-muted">JPG, GIF or PNG. Max size of 800K.</small><button class="outline-btn mt-2" onclick="toast('Profile image picker opened')">Upload New</button> <button class="outline-btn mt-2" onclick="toast('Profile picture removed')">Remove</button></div></div><div class="profile-grid"><div><label class="form-label">Full Name</label><input id="profileName" class="form-control-custom" value="Alex Rivera"></div><div><label class="form-label">Admin Role</label><input class="form-control-custom" value="Senior Systems Administrator" disabled></div><div><label class="form-label">Email Address</label><input id="profileEmail" class="form-control-custom" value="alex.rivera@eventify.com"></div><div><label class="form-label">Phone Number</label><input id="profilePhone" class="form-control-custom" value="+91 98765 43210"></div><div class="full"><label class="form-label">Professional Bio</label><textarea id="profileBio" class="form-control-custom textarea-custom">Leading the technical operations and event management workflows at Eventify.</textarea></div></div><div class="text-end mt-3"><button class="outline-btn" onclick="render('settings')">Cancel</button> <button class="dark-btn" onclick="saveProfile()">Save Profile Changes</button></div></div>`}
