function applySelectFilter(tableId, searchId, selects){
 const q=(document.getElementById(searchId)?.value||'').toLowerCase().trim();
 document.querySelectorAll(`#${tableId} tbody tr`).forEach(tr=>{
   const text=tr.innerText.toLowerCase();
   let ok=!q||text.includes(q);
   selects.forEach(sel=>{const el=document.getElementById(sel.id); if(el&&el.value) ok=ok&&text.includes(el.value.toLowerCase());});
   tr.style.display=ok?'':'none';
 });
}

function render(page){page=page||location.hash.slice(1)||'dashboard';if(page==='create')setActive('events');else setActive(page);currentPage=page;document.getElementById('content').innerHTML=({dashboard,events:eventsPage,create:createPage,bookings:bookingsPage,users:usersPage,organizers:organizersPage,payments:paymentsPage,reports:reportsPage,categories:categoriesPage,feedback:feedbackPage,settings:settingsPage}[page]||dashboard)();document.getElementById('topTitle').textContent=page==='create'?'Dashboard':(navItems.find(n=>n[0]===page)?.[1]||'Dashboard');if(page==='settings')bindSettings();window.scrollTo({top:0,behavior:'instant'})}
function bindSettings(){document.querySelectorAll('.settings-tab').forEach(b=>b.onclick=()=>{document.querySelectorAll('.settings-tab').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.getElementById('settingsTabContent').innerHTML=settingsTab(b.dataset.settingTab)})}
function toast(msg){const t=document.getElementById('toast');t.textContent=msg;t.classList.add('show');clearTimeout(window.__toast);window.__toast=setTimeout(()=>t.classList.remove('show'),1800)}
function saveEvent(){const name=document.getElementById('eventName')?.value.trim();if(!name){toast('Please enter an event name');return}const cat=document.getElementById('createCategory').value,loc=document.getElementById('eventLocation').value.trim()||'Venue to be confirmed',date=document.getElementById('eventDate').value||'TBD',p=document.getElementById('eventPrice').value.trim();const price=p?`₹${Number(p.replace(/[^0-9.]/g,'')||0).toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2})}`:'Free';data.events.unshift([name,cat,date,loc,price,document.getElementById('eventStatusCreate').value]);persist('events');toast('Event saved successfully');setTimeout(()=>render('events'),300)}
function editEvent(i){const e=data.events[i];if(!e)return;showModal('Edit Event',`<label class="form-label">Event Name</label><input id="editName" class="form-control-custom" value="${esc(e[0])}"><label class="form-label mt-3">Price (INR)</label><input id="editPrice" class="form-control-custom" value="${esc(e[4].replace(/[₹,]/g,''))}"><div class="text-end mt-3"><button class="dark-btn" onclick="commitEdit(${i})">Save Changes</button></div>`)}
function commitEdit(i){const n=document.getElementById('editName').value.trim(),p=document.getElementById('editPrice').value.replace(/[^0-9.]/g,'');if(n)data.events[i][0]=n;if(p)data.events[i][4]=`₹${Number(p).toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2})}`;persist('events');closeModal();toast('Event updated');render('events')}
