function filterTxnRows(){const q=(document.getElementById('txnSearch')?.value||'').toLowerCase().trim(),s=document.getElementById('txnStatus')?.value||'',m=document.getElementById('txnMethod')?.value||'';document.querySelectorAll('#txnTable tbody tr').forEach(tr=>{const t=tr.innerText.toLowerCase();tr.style.display=(!q||t.includes(q))&&(!s||t.includes(s.toLowerCase()))&&(!m||t.includes(m.toLowerCase()))?'':'none';});}
