function clearUserFilters(){['userSearch','userRole','userStatus'].forEach(id=>{const e=document.getElementById(id);if(e)e.value='';});filterUserRows();}
function filterBookingRows(){
 const q=(document.getElementById('bookingSearch')?.value||'').toLowerCase().trim(), s=document.getElementById('bookingStatus')?.value||'', e=document.getElementById('bookingEvent')?.value||'', p=document.getElementById('bookingPayment')?.value||'';
 document.querySelectorAll('#bookingTable tbody tr').forEach(tr=>{const t=tr.innerText.toLowerCase();tr.style.display=(!q||t.includes(q))&&(!s||t.includes(s.toLowerCase()))&&(!e||t.includes(e.toLowerCase()))&&(!p||t.includes(p.toLowerCase()))?'':'none';});
}
