function applyEventFilters(){
 const searchEl=document.getElementById('eventSearch'),statusEl=document.getElementById('eventStatus'),categoryEl=document.getElementById('eventCategory'),priceEl=document.getElementById('eventPrice');
 if(!searchEl||!statusEl||!categoryEl||!priceEl)return;
 const q=searchEl.value.trim().toLowerCase(),s=statusEl.value.trim().toLowerCase(),c=categoryEl.value.trim().toLowerCase(),p=priceEl.value.trim().toLowerCase();
 let visible=0;
 document.querySelectorAll('#eventsTable tbody tr').forEach(tr=>{
   const show=(!q||String(tr.dataset.search||'').toLowerCase().includes(q))&&(!s||String(tr.dataset.status||'').toLowerCase()===s)&&(!c||String(tr.dataset.category||'').toLowerCase()===c)&&(!p||String(tr.dataset.price||'').toLowerCase()===p);
   tr.style.display=show?'':'none';
   if(show)visible++;
 });
 const count=document.getElementById('eventFilterCount');if(count)count.textContent=`Showing ${visible} of ${data.events.length} events`;
}
function clearEventFilters(){['eventSearch','eventStatus','eventCategory','eventPrice'].forEach(id=>{const e=document.getElementById(id);if(e)e.value='';});applyEventFilters();}
