function exportCurrent(k,file){exportRows(data[k],file)}function exportRows(rows,file){const csv=rows.map(r=>r.map(v=>`"${String(v).replace(/"/g,'""')}"`).join(',')).join('\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=file;a.click();URL.revokeObjectURL(url);toast('CSV downloaded')}
function showModal(title,body){document.getElementById('modalTitle').textContent=title;document.getElementById('modalBody').innerHTML=body;bootstrap.Modal.getOrCreateInstance(document.getElementById('actionModal')).show()}function closeModal(){bootstrap.Modal.getOrCreateInstance(document.getElementById('actionModal')).hide()}
function manualBooking(){showModal('Manual Booking',`<label class="form-label">Customer Name</label><input id="manualCustomer" class="form-control-custom"><label class="form-label mt-3">Event</label><select id="manualEvent" class="form-select-custom">${data.events.map(e=>`<option>${e[0]}</option>`).join('')}</select><label class="form-label mt-3">Tickets</label><input id="manualTickets" type="number" min="1" value="1" class="form-control-custom"><div class="text-end mt-3"><button class="dark-btn" onclick="createBooking()">Create Booking</button></div>`)}
