function bookingAction(i){showModal('Booking '+data.bookings[i][0],`<p><b>${data.bookings[i][1]}</b> — ${data.bookings[i][2]}</p><p>Status: ${status(data.bookings[i][5])}</p><div class="d-flex gap-2"><button class="outline-btn" onclick="updateBooking(${i},'Confirmed')">Confirm</button><button class="outline-btn" onclick="updateBooking(${i},'Cancelled')">Cancel</button><button class="dark-btn" onclick="updateBooking(${i},'Refunded')">Refund</button></div>`)}
