function addCategory(){const n=prompt('Category name:');if(!n?.trim())return;const name=n.trim();if(data.events.some(e=>e[1].toLowerCase()===name.toLowerCase()))return toast('Category already exists');data.events.push([`${name} Launch Event`,name,'TBD','Venue to be confirmed','Free','Draft']);persist('events');toast('Category added');render('categories')}
