function inviteOrganizer(){showModal('Invite Organizer',`<label class="form-label">Organizer Name</label><input id="inviteName" class="form-control-custom"><label class="form-label mt-3">Email Address</label><input id="inviteEmail" type="email" class="form-control-custom"><div class="text-end mt-3"><button class="dark-btn" onclick="closeModal();toast('Organizer invitation sent')">Send Invitation</button></div>`)}
function orgData(){return [['ORG-001','Elena Rodriguez','elena@eventify.com','8','Active'],['ORG-002','Michael Chen','michael@eventify.com','5','Active'],['ORG-003','Sarah Jenkins','sarah@eventify.com','3','Pending'],['ORG-004','David Wilson','david@eventify.com','6','Active']]}
function viewOrganizer(n){showModal('Organizer Profile',`<h5>${n}</h5><p>Organizer profile, event activity and account details.</p><button class="dark-btn" onclick="closeModal()">Close</button>`)}function editOrganizer(n){showModal('Edit Organizer',`<label class="form-label">Organizer Name</label><input class="form-control-custom" value="${esc(n)}"><div class="text-end mt-3"><button class="dark-btn" onclick="closeModal();toast('Organizer changes saved')">Save</button></div>`)}
function reviewFeedback(n){showModal('Feedback Review',`<p>Review submitted by <b>${n}</b>.</p><button class="dark-btn" onclick="closeModal();toast('Feedback marked as reviewed')">Mark Reviewed</button>`)}
function generateReport(){toast('Report generated successfully')}
function saveProfile(){localStorage.setItem('eventify_profile',JSON.stringify({name:document.getElementById('profileName').value,email:document.getElementById('profileEmail').value,phone:document.getElementById('profilePhone').value,bio:document.getElementById('profileBio').value}));toast('Profile changes saved')}
function logout(){if(confirm('Log out from Eventify Admin?')){sessionStorage.removeItem('eventify_admin_session');toast('Logged out successfully')}}
function esc(s){return String(s).replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/'/g,'&#39;')}
document.getElementById('globalSearch').addEventListener('keydown',e=>{if(e.key!=='Enter')return;const q=e.target.value.trim().toLowerCase();if(!q)return toast('Please enter something to search');const hit=data.events.find(x=>x.join(' ').toLowerCase().includes(q));if(hit){location.hash='events';render('events');setTimeout(()=>{document.getElementById('eventSearch').value=q;applyEventFilters()},50);return}const b=data.bookings.find(x=>x.join(' ').toLowerCase().includes(q));if(b){location.hash='bookings';render('bookings');setTimeout(()=>{document.getElementById('bookingSearch').value=q;filterGeneric('bookingSearch','bookingTable')},50);return}toast('No matching record found')});
window.addEventListener('hashchange',()=>render(location.hash.slice(1)));nav();render(location.hash.slice(1)||'dashboard');
